with target as (select d.id,d.status,c.id company_id,c.name,c.account_id,u.email owner_email from public.team_diagnostics d join public.company_profiles c on c.id=d.company_id join auth.users u on u.id=c.owner_user_id where d.id='faa8e71b-b2dc-4dd8-a222-2b7d58d75e23'::uuid and c.id='1a4e564d-95e2-4ae1-865f-266cde5f28f9'::uuid and lower(u.email)='audit_1@iteam.ru'), e as(select private.team_numeric_evidence_v2(id) v from target), g as(select q.pos,count(*) filter(where nullif(btrim(r.answers->>(q.item->>'id')),'') is not null) n,sum(char_length(r.answers->>(q.item->>'id'))) chars from target t join private.team_questionnaires tq on tq.team_diagnostic_id=t.id cross join lateral jsonb_array_elements(tq.questions) with ordinality q(item,pos) cross join lateral private.team_completed(t.id) r where q.item->>'answer_type'='text' group by q.pos) select t.*,s.completed_count,s.fingerprint,e.v->'overall' overall,e.v->'blocks' blocks,jsonb_array_length(e.v->'questions') question_count,(select jsonb_agg(jsonb_build_object('position',pos,'eligible',n>=3,'count',n,'characters',chars) order by pos) from g) text_group_metadata,(select count(*) from public.team_ai_reports where team_diagnostic_id=t.id) reports_count,(select encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(a) order by a.version),'[]'::jsonb)::text,'UTF8')),'hex') from public.team_ai_reports a where a.team_diagnostic_id=t.id) historical_reports_guard,(select encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by r.participant_id),'[]'::jsonb)::text,'UTF8')),'hex') from private.team_responses r join public.team_participants p on p.id=r.participant_id where p.team_diagnostic_id=t.id) response_guard,(select md5(pg_get_functiondef('private.validate_team_output(uuid,jsonb)'::regprocedure))) validator_md5 from target t cross join lateral private.team_source(t.id) s cross join e;
